-- READ ONLY: application DDL/security metadata; no patient/Auth rows, Storage object paths or secrets.
-- Fixed projects are selected by the caller. This query does not apply/reconcile migrations.
set local search_path = pg_catalog;
select jsonb_build_object(
'server', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select current_setting('server_version') as version, current_setting('server_version_num') as version_num, current_setting('server_encoding') as encoding, (select datcollate from pg_database where datname=current_database()) as collation, (select datctype from pg_database where datname=current_database()) as ctype) q),
'schemas', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select nspname as schema, pg_get_userbyid(nspowner) as owner, nspacl::text as acl from pg_namespace where nspname in ('public','app','extensions','auth','storage') order by nspname) q),
'extensions', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select e.extname as name,n.nspname as schema,e.extversion as version,e.extrelocatable as relocatable from pg_extension e join pg_namespace n on n.oid=e.extnamespace order by e.extname) q),
'relations', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,c.relname as name,c.relkind as kind,pg_get_userbyid(c.relowner) as owner,c.relpersistence as persistence,c.relrowsecurity as rls,c.relforcerowsecurity as force_rls,c.relreplident as replica_identity,c.reloptions as options,c.relacl::text as acl,c.relispartition as is_partition,case when c.relispartition then pg_get_expr(c.relpartbound,c.oid) end as partition_bound,case when c.relkind='p' then pg_get_partkeydef(c.oid) end as partition_key,case when c.relkind in ('v','m') then pg_get_viewdef(c.oid,true) end as view_definition from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app') and c.relkind in ('r','p','v','m','S','f') and not exists(select 1 from pg_depend d where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='e') order by n.nspname,c.relname) q),
'columns', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,c.relname as relation,a.attnum as ordinal,a.attname as name,format_type(a.atttypid,a.atttypmod) as type,a.attnotnull as not_null,a.attidentity as identity,a.attgenerated as generated,a.attstorage as storage,a.attcompression as compression,a.attstattarget as statistics_target,a.attoptions as options,case when a.attcollation <> t.typcollation then (select quote_ident(cn.nspname)||'.'||quote_ident(co.collname) from pg_collation co join pg_namespace cn on cn.oid=co.collnamespace where co.oid=a.attcollation) end as collation,pg_get_expr(ad.adbin,ad.adrelid) as default_expression,a.attacl::text as acl from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped join pg_type t on t.oid=a.atttypid left join pg_attrdef ad on ad.adrelid=c.oid and ad.adnum=a.attnum where n.nspname in ('public','app') and c.relkind in ('r','p','v','m','f') and not exists(select 1 from pg_depend d where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='e') order by n.nspname,c.relname,a.attnum) q),
'constraints', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,c.relname as relation,k.conname as name,k.contype as type,k.convalidated as validated,k.condeferrable as "deferrable",k.condeferred as deferred,pg_get_constraintdef(k.oid,true) as definition from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app') order by n.nspname,c.relname,k.conname) q),
'indexes', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,t.relname as relation,i.relname as name,pg_get_indexdef(i.oid) as definition,x.indisunique as "unique",x.indisprimary as "primary",x.indisvalid as valid,x.indisready as ready,x.indisclustered as clustered,x.indisreplident as replica_identity,i.reloptions as options,(select spcname from pg_tablespace where oid=i.reltablespace) as tablespace,exists(select 1 from pg_constraint k where k.conindid=i.oid) as constraint_owned from pg_index x join pg_class i on i.oid=x.indexrelid join pg_class t on t.oid=x.indrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname in ('public','app') order by n.nspname,t.relname,i.relname) q),
'sequences', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,c.relname as name,format_type(s.seqtypid,null) as type,s.seqstart::text as start,s.seqincrement::text as increment,s.seqmax::text as maximum,s.seqmin::text as minimum,s.seqcache::text as cache,s.seqcycle as cycle,(select jsonb_agg(jsonb_build_object('schema',tn.nspname,'relation',tc.relname,'column',a.attname,'dependency_type',d.deptype) order by tn.nspname,tc.relname,a.attname) from pg_depend d join pg_class tc on tc.oid=d.refobjid join pg_namespace tn on tn.oid=tc.relnamespace join pg_attribute a on a.attrelid=tc.oid and a.attnum=d.refobjsubid where d.classid='pg_class'::regclass and d.objid=c.oid and d.refclassid='pg_class'::regclass and d.deptype in ('a','i')) as ownership from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app') order by n.nspname,c.relname) q),
'types', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,t.typname as name,t.typtype as kind,pg_get_userbyid(t.typowner) as owner,t.typacl::text as acl,case when t.typtype='d' then format_type(t.typbasetype,t.typtypmod) end as base_type,t.typnotnull as not_null,t.typdefault as default_expression,(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid) as enum_values,(select jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid,true),'validated',k.convalidated) order by k.conname) from pg_constraint k where k.contypid=t.oid) as constraints from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','app') and t.typtype in ('e','d','c','r','m') and (t.typrelid=0 or exists(select 1 from pg_class c where c.oid=t.typrelid and c.relkind='c')) and not exists(select 1 from pg_depend d where d.classid='pg_type'::regclass and d.objid=t.oid and d.deptype='e') order by n.nspname,t.typname) q),
'functions', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,p.proname as name,pg_get_function_identity_arguments(p.oid) as arguments,p.prokind as kind,pg_get_userbyid(p.proowner) as owner,l.lanname as language,p.prosecdef as security_definer,p.provolatile as volatility,p.proparallel as parallel,p.proisstrict as strict,p.proleakproof as leakproof,p.proconfig as settings,p.proacl::text as acl,pg_get_functiondef(p.oid) as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','app') and p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e') order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) q),
'policies', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select schemaname as schema,tablename as relation,policyname as name,permissive,roles,cmd as command,qual as using_expression,with_check as check_expression from pg_policies where schemaname in ('public','app','storage') order by schemaname,tablename,policyname) q),
'triggers', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,c.relname as relation,g.tgname as name,g.tgenabled as enabled,pn.nspname as function_schema,p.proname as function_name,pg_get_triggerdef(g.oid,true) as definition from pg_trigger g join pg_class c on c.oid=g.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=g.tgfoid join pg_namespace pn on pn.oid=p.pronamespace where not g.tgisinternal and (n.nspname in ('public','app') or (n.nspname in ('auth','storage') and pn.nspname in ('public','app'))) order by n.nspname,c.relname,g.tgname) q),
'rules', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,c.relname as relation,r.rulename as name,r.ev_enabled as enabled,pg_get_ruledef(r.oid,true) as definition from pg_rewrite r join pg_class c on c.oid=r.ev_class join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app') and r.rulename<>'_RETURN' order by n.nspname,c.relname,r.rulename) q),
'default_privileges', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select pg_get_userbyid(d.defaclrole) as owner,n.nspname as schema,d.defaclobjtype as object_type,d.defaclacl::text as acl from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where d.defaclnamespace=0 or n.nspname in ('public','app','extensions','auth','storage') order by pg_get_userbyid(d.defaclrole),coalesce(n.nspname,''),d.defaclobjtype) q),
'publications', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select p.pubname as name,pg_get_userbyid(p.pubowner) as owner,p.puballtables as all_tables,p.pubinsert as inserts,p.pubupdate as updates,p.pubdelete as deletes,p.pubtruncate as truncates,p.pubviaroot as via_partition_root,(select jsonb_agg(jsonb_build_object('schema',t.schemaname,'relation',t.tablename,'columns',t.attnames,'row_filter',t.rowfilter) order by t.schemaname,t.tablename) from pg_publication_tables t where t.pubname=p.pubname) as tables from pg_publication p where p.pubname='supabase_realtime' order by p.pubname) q),
'storage_relation_security', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select c.relname as name,c.relrowsecurity as rls,c.relforcerowsecurity as force_rls,c.relacl::text as acl from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='storage' and c.relkind in ('r','p') order by c.relname) q),
'storage_buckets', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select id,public,file_size_limit::text as file_size_limit,allowed_mime_types from storage.buckets order by id) q),
'migration_history', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select version,name,cardinality(statements) as statement_count from supabase_migrations.schema_migrations order by version) q),
'effective_grants', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select 'schema' as kind,n.nspname as schema,null::text as relation,n.nspname as name,null::text as arguments,case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end as grantee,pg_get_userbyid(x.grantor) as grantor,x.privilege_type as privilege,x.is_grantable as grantable from pg_namespace n cross join lateral aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x where n.nspname in ('public','app','extensions','auth','storage') union all select case when c.relkind='S' then 'sequence' else 'relation' end,n.nspname,null::text,c.relname,null::text,case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))) x where n.nspname in ('public','app','storage') and c.relkind in ('r','p','v','m','S','f') and not exists(select 1 from pg_depend d where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='e') union all select 'function',n.nspname,null::text,p.proname,pg_get_function_identity_arguments(p.oid),case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x where n.nspname in ('public','app') and p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e') union all select 'column',n.nspname,c.relname,a.attname,null::text,case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(a.attacl) x where n.nspname in ('public','app') and a.attnum>0 and not a.attisdropped union all select 'type',n.nspname,null::text,t.typname,null::text,case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,pg_get_userbyid(x.grantor),x.privilege_type,x.is_grantable from pg_type t join pg_namespace n on n.oid=t.typnamespace cross join lateral aclexplode(coalesce(t.typacl,acldefault('T',t.typowner))) x where n.nspname in ('public','app') and t.typtype in ('e','d') and not exists(select 1 from pg_depend d where d.classid='pg_type'::regclass and d.objid=t.oid and d.deptype='e') order by kind,schema,relation,name,arguments,grantee,grantor,privilege,grantable) q),
'table_inheritance', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select n.nspname as schema,c.relname as relation,pn.nspname as parent_schema,p.relname as parent,i.inhseqno as ordinal from pg_inherits i join pg_class c on c.oid=i.inhrelid join pg_namespace n on n.oid=c.relnamespace join pg_class p on p.oid=i.inhparent join pg_namespace pn on pn.oid=p.relnamespace where n.nspname in ('public','app') order by n.nspname,c.relname,i.inhseqno) q),
'coverage', (select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) from (select 'app_relations_outside_supported_kinds' as "check",count(*) as total from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app') and c.relkind not in ('r','p','v','m','S','i','I','t','c') and not exists(select 1 from pg_depend d where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='e') union all select 'app_aggregates',count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','app') and p.prokind='a' and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e') union all select 'app_operators',count(*) from pg_operator o join pg_namespace n on n.oid=o.oprnamespace where n.nspname in ('public','app') and not exists(select 1 from pg_depend d where d.classid='pg_operator'::regclass and d.objid=o.oid and d.deptype='e') union all select 'app_composite_range_types',count(*) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','app') and (t.typtype in ('r','m') or (t.typtype='c' and exists(select 1 from pg_class c where c.oid=t.typrelid and c.relkind='c'))) and not exists(select 1 from pg_depend d where d.classid='pg_type'::regclass and d.objid=t.oid and d.deptype='e') union all select 'app_foreign_tables',count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','app') and c.relkind='f' order by "check") q)
) as catalog;
